package main

import (
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

var officialMediumFizProfiles = []string{
	"fiz-harness-claude-sonnet-4-6",
	"fiz-harness-codex-gpt-5-4-mini",
	"fiz-harness-pi-gpt-5-4-mini",
	"fiz-harness-opencode-gpt-5-4-mini",
	"fiz-openrouter-claude-sonnet-4-6",
	"fiz-openrouter-gpt-5-4-mini",
}

func officialMediumFizProfilesCSV() string {
	return strings.Join(officialMediumFizProfiles, ",")
}

func TestMediumTerminalbenchComparisonProfilesAreOfficialFizLanes(t *testing.T) {
	repoRoot := benchRepoRoot(t)
	outDir := t.TempDir()

	code := cmdMatrix([]string{
		"--work-dir", repoRoot,
		"--harnesses", "noop",
		"--profiles", officialMediumFizProfilesCSV(),
		"--reps", "1",
		"--out", outDir,
	})
	if code != 0 {
		t.Fatalf("cmdMatrix exit = %d, want 0", code)
	}

	matrix := readMatrixOutput(t, filepath.Join(outDir, "matrix.json"))
	if !reflect.DeepEqual(matrix.Profiles, officialMediumFizProfiles) {
		t.Fatalf("matrix profiles = %v, want %v", matrix.Profiles, officialMediumFizProfiles)
	}
}

func TestRunMediumModelComparisonScriptUsesOnlyFizHarborAgent(t *testing.T) {
	repoRoot := benchRepoRoot(t)

	t.Run("default_force_build", func(t *testing.T) {
		lines := runMediumComparisonScript(t, repoRoot, map[string]string{})
		matrixLine := findLineContaining(t, lines, "matrix --profiles=")
		normalized := strings.ReplaceAll(matrixLine, `\,`, ",")
		if !strings.Contains(matrixLine, "--harnesses=fiz") {
			t.Fatalf("matrix invocation does not pin Harbor to fiz: %s", matrixLine)
		}
		if !strings.Contains(normalized, officialMediumFizProfilesCSV()) {
			t.Fatalf("matrix invocation missing official profile CSV: %s", matrixLine)
		}
		buildLine := findLineContaining(t, lines, " build ")
		if !strings.Contains(buildLine, "HARBOR_FORCE_BUILD=1") {
			t.Fatalf("default run should set HARBOR_FORCE_BUILD=1: %s", buildLine)
		}
	})

	t.Run("force_build_override", func(t *testing.T) {
		lines := runMediumComparisonScript(t, repoRoot, map[string]string{
			"HARBOR_FORCE_BUILD": "0",
		})
		buildLine := findLineContaining(t, lines, " build ")
		if !strings.Contains(buildLine, "HARBOR_FORCE_BUILD=0") {
			t.Fatalf("override run should preserve HARBOR_FORCE_BUILD=0: %s", buildLine)
		}
		matrixLine := findLineContaining(t, lines, "matrix --profiles=")
		normalized := strings.ReplaceAll(matrixLine, `\,`, ",")
		if !strings.Contains(matrixLine, "--harnesses=fiz") {
			t.Fatalf("matrix invocation does not pin Harbor to fiz: %s", matrixLine)
		}
		if !strings.Contains(normalized, officialMediumFizProfilesCSV()) {
			t.Fatalf("matrix invocation missing official profile CSV: %s", matrixLine)
		}
	})
}

func findLineContaining(t *testing.T, lines []string, needle string) string {
	t.Helper()
	for _, line := range lines {
		if strings.Contains(line, needle) {
			return line
		}
	}
	t.Fatalf("did not find line containing %q in %v", needle, lines)
	return ""
}

func runMediumComparisonScript(t *testing.T, repoRoot string, extraEnv map[string]string) []string {
	t.Helper()

	binDir := t.TempDir()
	goLog := filepath.Join(binDir, "go.log")
	goPath := filepath.Join(binDir, "go")
	harborPath := filepath.Join(binDir, "harbor")
	goWrapper := `#!/usr/bin/env bash
set -euo pipefail
{
  printf 'HARBOR_FORCE_BUILD=%s ' "${HARBOR_FORCE_BUILD:-}"
  printf '%q ' go "$@"
  printf '\n'
} >> "$GO_LOG"
case "${1:-}" in
  build)
    out=""
    while (($#)); do
      case "$1" in
        -o)
          out="$2"
          shift 2
          ;;
        *)
          shift
          ;;
      esac
    done
    if [[ -n "$out" ]]; then
      mkdir -p "$(dirname "$out")"
      printf '#!/usr/bin/env bash\nexit 0\n' > "$out"
      chmod 755 "$out"
    fi
    ;;
  run)
    ;;
esac
exit 0
`
	if err := os.WriteFile(goPath, []byte(goWrapper), 0o755); err != nil {
		t.Fatalf("write fake go: %v", err)
	}

	harborWrapper := `#!/usr/bin/env bash
set -euo pipefail
exit 0
`
	if err := os.WriteFile(harborPath, []byte(harborWrapper), 0o755); err != nil {
		t.Fatalf("write fake harbor: %v", err)
	}

	cmd := exec.Command("bash", filepath.Join(repoRoot, "scripts", "benchmark", "run_medium_model_terminalbench_comparison.sh"), "canary")
	cmd.Dir = repoRoot
	cmd.Env = make([]string, 0, len(os.Environ())+5)
	for _, kv := range os.Environ() {
		switch {
		case strings.HasPrefix(kv, "PATH="):
			continue
		case strings.HasPrefix(kv, "OPENROUTER_API_KEY="):
			continue
		case strings.HasPrefix(kv, "GOFLAGS="):
			continue
		case strings.HasPrefix(kv, "GO_LOG="):
			continue
		}
		cmd.Env = append(cmd.Env, kv)
	}
	cmd.Env = append(cmd.Env,
		"PATH="+binDir+string(os.PathListSeparator)+os.Getenv("PATH"),
		"OPENROUTER_API_KEY=dummy",
		"GOFLAGS=-buildvcs=false",
		"GO_LOG="+goLog,
	)
	for k, v := range extraEnv {
		cmd.Env = append(cmd.Env, k+"="+v)
	}
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("medium comparison script failed: %v\n%s", err, string(out))
	}

	raw, err := os.ReadFile(goLog)
	if err != nil {
		t.Fatalf("read go log: %v", err)
	}
	lines := strings.Split(strings.TrimSpace(string(raw)), "\n")
	if len(lines) == 1 && lines[0] == "" {
		return nil
	}
	return lines
}

				profile:           spec.prof,
				rep:               spec.rep,
				task:              spec.task,
				budgetUSD:         *budgetUSD,
				perRunBudgetUSD:   *perRunBudgetUSD,
				accumulatedCost:   cost,
				resume:            *resume,
				forceRerun:        *forceRerun,
				retryBudgetHalted: *retryBudgetHalted,
				tasksDir:          resolvedTasksDir,
				harborBin:         harborBin,
			})

			mu.Lock()
			results[i] = tupleResult{report, skipped, err}
			if err != nil && firstErr == nil {
				firstErr = err
			}
			if err == nil && !skipped {
				accumulatedCost += report.CostUSD
			}
			mu.Unlock()
		}(i, spec)
	}
	wg.Wait()

	if firstErr != nil {
		fmt.Fprintf(os.Stderr, "%s matrix: %v\n", benchCommandName(), firstErr)
		return 1
	}

	var runs []matrixRunReport
	for _, r := range results {
		runs = append(runs, r.report)
	}

	sort.Slice(runs, func(i, j int) bool {
		return matrixRunKey(runs[i]) < matrixRunKey(runs[j])
	})
	output := matrixOutput{
		GeneratedAt:     time.Now().UTC(),
		SubsetPath:      subsetPath,
		Profiles:        profileIDs,
		Harnesses:       harnesses,
		Reps:            *reps,
		BudgetUSD:       *budgetUSD,
		PerRunBudgetUSD: *perRunBudgetUSD,
		Runs:            runs,
		Cells:           summarizeMatrixCells(runs),
		Notes: []string{
			fmt.Sprintf("concurrency: --jobs %d", concurrency),
			"adapter_module records the Python adapter path passed by the runner for the harness cell.",
		},
	}
	matrixPath := filepath.Join(outDir, "matrix.json")
	if err := writeJSONAtomic(matrixPath, output); err != nil {
		fmt.Fprintf(os.Stderr, "%s matrix: write matrix.json: %v\n", benchCommandName(), err)
		return 1
	}
	fmt.Printf("matrix results: %s\n", matrixPath)
	return 0
}

type matrixTupleOptions struct {
	workDir           string
	outDir            string
	harness           string
	profile           *profile.Profile
	rep               int
	task              termbenchSubsetEntry
	budgetUSD         float64
	perRunBudgetUSD   float64
	accumulatedCost   float64
	resume            bool
	forceRerun        bool
	retryBudgetHalted bool
	tasksDir          string // when set, use harbor run for grading
	harborBin         string // path to harbor binary
}

func runMatrixTuple(opts matrixTupleOptions) (matrixRunReport, bool, error) {
	cellDir := matrixTupleDir(opts.outDir, opts.harness, opts.profile.ID, opts.rep, opts.task.ID)
	reportPath := filepath.Join(cellDir, matrixReportName)
	if !opts.forceRerun {
		if existing, ok, err := loadExistingMatrixReport(reportPath); err != nil {
			return matrixRunReport{}, false, err
		} else if ok && shouldSkipMatrixReport(existing, opts.resume, opts.retryBudgetHalted) {
			return existing, true, nil
		}
	}

	release, err := acquireMatrixLock(filepath.Join(cellDir, matrixLockName))
	if err != nil {
		return matrixRunReport{}, false, err
	}
	defer release()

	started := time.Now().UTC()
	report := matrixRunReport{
		Harness:         opts.harness,
		ProfileID:       opts.profile.ID,
		ProfilePath:     opts.profile.Path,
		ProfileSnapshot: opts.profile.Versioning.Snapshot,
		AdapterModule:   matrixAdapterModule(opts.harness),
		HarborAgent:     filepath.ToSlash(filepath.Join("scripts", "benchmark", "harness_adapters", moduleFileName(opts.harness))) + ":Agent",
		Rep:             opts.rep,
		TaskID:          opts.task.ID,
		Category:        opts.task.Category,
		Difficulty:      opts.task.Difficulty,
		OutputDir:       cellDir,
		StartedAt:       started,
		PricingSource:   profilePricingSource(opts.profile),
		SamplingUsed:    samplingUsedFromProfile(opts.profile),
		ModelServerInfo: queryModelServerInfo(opts.profile),
	}

	if opts.budgetUSD > 0 && opts.accumulatedCost >= opts.budgetUSD {
		report.ProcessOutcome = "budget_halted"
		report.GradingOutcome = "ungraded"
		report.FinalStatus = deriveMatrixFinalStatus(report.ProcessOutcome, report.GradingOutcome, report.Reward, false)
		report.FinishedAt = time.Now().UTC()
		if err := writeJSONAtomic(reportPath, report); err != nil {
			return matrixRunReport{}, false, err
		}
		return report, false, nil
	}

	workDir := filepath.Join(cellDir, "work")
	if err := os.MkdirAll(workDir, 0o750); err != nil {
		return matrixRunReport{}, false, fmt.Errorf("create tuple workdir: %w", err)
	}

	if opts.harborBin != "" {
		taskPath := filepath.Join(opts.tasksDir, opts.task.ID)
		if _, err := os.Stat(taskPath); err != nil {
			report.ProcessOutcome = "install_fail_permanent"
			report.GradingOutcome = "ungraded"
			report.Error = fmt.Sprintf("task directory not found: %s", taskPath)
		} else {
			harborResult, err := runMatrixHarbor(harborRunOpts{
				harborBin: opts.harborBin,
				taskPath:  taskPath,
				harness:   opts.harness,
				profile:   opts.profile,
				jobsDir:   cellDir,
				jobName:   fmt.Sprintf("%s-%s-rep%d", opts.harness, opts.task.ID, opts.rep),
				repoRoot:  opts.workDir,
			})
			if err != nil {
				report.ProcessOutcome = "harness_crash"
				report.GradingOutcome = "ungraded"
				report.Error = err.Error()
			} else {
				report.ExitCode = harborResult.exitCode
				report.Error = harborResult.errText
				seconds := harborResult.wallSeconds
				report.WallSeconds = &seconds
				if harborResult.reward != nil {
					report.Reward = harborResult.reward
					report.GradingOutcome = "graded"
					report.ProcessOutcome = "completed"
				} else if harborResult.exitCode != 0 {
					report.ProcessOutcome = "harness_crash"
					report.GradingOutcome = "ungraded"
				} else {
					report.ProcessOutcome = "completed"
					report.GradingOutcome = "ungraded"
				}
			}
		}
	} else {
		result, err := runMatrixAdapter(opts.workDir, report.AdapterModule, opts.profile, matrixPrompt(opts.task), opts.task.ID, workDir)
		if err != nil {
			report.ProcessOutcome = "harness_crash"
			report.GradingOutcome = "ungraded"
			report.Error = err.Error()
		} else {
			report.Command = result.Command.Argv
			report.AdapterTranslationNotes = append(report.AdapterTranslationNotes, result.Apply.Notes...)
			report.AdapterTranslationNotes = append(report.AdapterTranslationNotes, result.Command.Notes...)
			report.ExitCode = result.ExitCode
			if result.ExitCode != 0 {
				report.ProcessOutcome = "harness_crash"
				report.Error = strings.TrimSpace(result.Stderr)
			}
			applyTelemetry(&report, result.Telemetry)
			if report.WallSeconds == nil && result.Duration >= 0 {
				seconds := float64(result.Duration) / 1000
				report.WallSeconds = &seconds
			}
		}
	}
	if report.ProcessOutcome == "" {
		report.ProcessOutcome = "completed"
	}
	if report.GradingOutcome == "" {
		report.GradingOutcome = "ungraded"
	}
	if report.Reward != nil && report.GradingOutcome == "ungraded" {
		report.GradingOutcome = "graded"
	}
	report.CostUSD = matrixCostUSD(opts.profile, report)
	if (opts.perRunBudgetUSD > 0 && report.CostUSD > opts.perRunBudgetUSD) ||
		(opts.budgetUSD > 0 && opts.accumulatedCost+report.CostUSD > opts.budgetUSD) {
		report.ProcessOutcome = "budget_halted"
		report.GradingOutcome = "ungraded"
		report.Reward = nil
	}
	report.FinalStatus = deriveMatrixFinalStatus(report.ProcessOutcome, report.GradingOutcome, report.Reward, report.Retriable)
	report.InvalidClass = classifyMatrixInvalid(report)
	report.FinishedAt = time.Now().UTC()
	if err := writeJSONAtomic(reportPath, report); err != nil {
		return matrixRunReport{}, false, err
	}
	return report, false, nil
}

type harborRunOpts struct {
	harborBin string
	taskPath  string
	harness   string
	profile   *profile.Profile
	jobsDir   string
	jobName   string
	repoRoot  string
}

type harborRunResult struct {
	reward      *int
	exitCode    int
	wallSeconds float64
	errText     string
}

// harborAgentArgs returns the agent selection args for harbor run.
// All benchmarked harnesses use repo-owned adapters so profile translation is
// identical between local command-builder smokes and Harbor-graded runs.
func harborAgentArgs(harness string) []string {
	switch harness {
	case "claude":
		return []string{"--agent-import-path", "scripts.benchmark.harbor_adapters.claude:ClaudeAgent"}
	case "codex":
		return []string{"--agent-import-path", "scripts.benchmark.harbor_adapters.codex:CodexAgent"}
	case "opencode":
		return []string{"--agent-import-path", "scripts.benchmark.harbor_adapters.opencode:OpencodeAgent"}
	case "pi":
		return []string{"--agent-import-path", "scripts.benchmark.harbor_adapters.pi:PiAgent"}
	default: // fiz
		return []string{"--agent-import-path", "scripts.benchmark.harbor_agent:FizeauAgent"}
	}
}

func runMatrixHarbor(opts harborRunOpts) (harborRunResult, error) {
	started := time.Now()

	apiKeyEnv := opts.profile.Provider.APIKeyEnv
	apiKeyVal := os.Getenv(apiKeyEnv)

	args := []string{"run", "--yes", "--path", opts.taskPath}
	args = append(args, harborAgentArgs(opts.harness)...)
	args = append(args,

	args = append(args,
		"--model", opts.profile.Provider.Model,
		"--jobs-dir", opts.jobsDir,
		"--job-name", opts.jobName,
	)
	if truthyEnv("HARBOR_FORCE_BUILD") {
		args = append(args, "--force-build")
	}
	if multiplier := strings.TrimSpace(os.Getenv("HARBOR_AGENT_TIMEOUT_MULTIPLIER")); multiplier != "" {
		args = append(args, "--agent-timeout-multiplier", multiplier)
	}
	if apiKeyVal != "" {
		args = append(args, "--ae", apiKeyEnv+"="+apiKeyVal)
	}
	// Pass provider config so Harbor agents can configure the model endpoint.
	args = append(args,
		"--ae", "FIZEAU_BASE_URL="+opts.profile.Provider.BaseURL,
		"--ae", "FIZEAU_MODEL="+opts.profile.Provider.Model,
		"--ae", "FIZEAU_PROVIDER="+fizeauProviderEnv(opts.profile),
	)
	if apiKeyVal != "" {
		args = append(args, "--ae", "FIZEAU_API_KEY="+apiKeyVal)
	}
	// Forward sampling params so fiz reads them via FIZEAU_* env overrides.
	for _, kv := range samplingEnvPairs(opts.profile) {
		args = append(args, "--ae", kv)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 35*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, opts.harborBin, args...) // #nosec G204 G702 -- harborBin is a validated binary path from config
	// Add repo root to PYTHONPATH so harbor_adapters modules resolve.
	env := os.Environ()
	pythonPath := opts.repoRoot
	for i, e := range env {
		if strings.HasPrefix(e, "PYTHONPATH=") {
			pythonPath = opts.repoRoot + string(os.PathListSeparator) + e[len("PYTHONPATH="):]
			env[i] = "PYTHONPATH=" + pythonPath
			pythonPath = ""
			break
		}
	}
	if pythonPath != "" {
		env = append(env, "PYTHONPATH="+pythonPath)
	}
	cmd.Env = env
	cmd.Dir = opts.repoRoot

	var combined bytes.Buffer
	cmd.Stdout = &combined
	cmd.Stderr = &combined
	runErr := cmd.Run()
	wall := time.Since(started).Seconds()

	exitCode := 0
	if runErr != nil {
		var ee *exec.ExitError
		if errors.As(runErr, &ee) {
			exitCode = ee.ExitCode()
		} else {
			return harborRunResult{}, runErr
		}
	}

	// Find reward.txt written by the Harbor verifier.
	var reward *int
	jobOutDir := filepath.Join(opts.jobsDir, opts.jobName)
	entries, _ := os.ReadDir(jobOutDir)
	for _, e := range entries {
		rewardFile := filepath.Join(jobOutDir, e.Name(), "verifier", "reward.txt")
		data, err := os.ReadFile(rewardFile) // #nosec G304 -- rewardFile is under runner-owned output dir
		if err == nil {
			val, err := strconv.Atoi(strings.TrimSpace(string(data)))
			if err == nil {
				reward = &val
			}
			break
		}
	}

	errText := ""
	if exitCode != 0 || reward == nil {
		errText = strings.TrimSpace(combined.String())
		if len(errText) > 2000 {
			errText = errText[:2000]
		}
	}
	return harborRunResult{
		reward:      reward,
		exitCode:    exitCode,
		wallSeconds: wall,
		errText:     errText,
	}, nil
}

func runMatrixAdapter(repoRoot, module string, prof *profile.Profile, prompt, taskID, workDir string) (matrixAdapterResult, error) {
	profileJSON, err := json.Marshal(adapterProfileMapping(prof))
	if err != nil {
		return matrixAdapterResult{}, err
	}
	script := `
import importlib, json, os, subprocess, sys, time
from scripts.benchmark.harness_adapters.base import BenchmarkProfile

module = importlib.import_module(sys.argv[1])
profile_raw = json.loads(sys.argv[2])
prompt = sys.argv[3]
task_id = sys.argv[4]
workdir = sys.argv[5]
agent = module.Agent()
profile = BenchmarkProfile.from_mapping(profile_raw)
apply = agent.apply_profile(profile)
command = agent.command(profile, prompt, workdir)
env = os.environ.copy()
env.update(getattr(apply, "env", {}) or {})
env.update(getattr(command, "env", {}) or {})
started = time.time()
stdout = ""
stderr = ""
exit_code = 0
argv = list(getattr(command, "argv", []) or [])
if argv:
    proc = subprocess.run(
        argv,
        input=getattr(command, "stdin", None),
        text=True,
        capture_output=True,
        cwd=getattr(command, "cwd", None) or workdir,
        env=env,
        timeout=1800,
    )
    stdout = proc.stdout
    stderr = proc.stderr
    exit_code = proc.returncode
duration_ms = int((time.time() - started) * 1000)
stream = task_id + "\n" + stdout + "\n" + stderr
telemetry = agent.parse_telemetry(stream)
def spec_to_dict(spec):
    return {
        "argv": list(getattr(spec, "argv", []) or []),
        "env": dict(getattr(spec, "env", {}) or {}),
        "notes": list(getattr(spec, "notes", []) or []),
        "cwd": getattr(spec, "cwd", None) or "",
    }
print(json.dumps({
    "telemetry": telemetry,
    "apply": spec_to_dict(apply),
    "command": spec_to_dict(command),
    "stdout": stdout,
    "stderr": stderr,
    "exit_code": exit_code,
    "duration_ms": duration_ms,
}, sort_keys=True))
`
	ctx, cancel := context.WithTimeout(context.Background(), 31*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, "python3", "-c", script, module, string(profileJSON), prompt, taskID, workDir) // #nosec G204 -- python3 is a fixed system binary
	cmd.Dir = repoRoot
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if ctx.Err() != nil {
		return matrixAdapterResult{}, ctx.Err()
	}
	if err != nil {
		if stderr.Len() > 0 {
			return matrixAdapterResult{}, fmt.Errorf("%w: %s", err, strings.TrimSpace(stderr.String()))
		}
		return matrixAdapterResult{}, err
	}
	var result matrixAdapterResult
	if err := json.Unmarshal(out, &result); err != nil {
		return matrixAdapterResult{}, fmt.Errorf("parse adapter result: %w", err)
	}
	return result, nil
}

func selectMatrixProfiles(workDir string, ids []string) ([]*profile.Profile, error) {
	profilesDir := filepath.Join(workDir, defaultProfilesDir)
	loaded, err := profile.LoadDir(profilesDir)
	if err != nil {
		return nil, err
	}
	byID := map[string]*profile.Profile{}
	for _, p := range loaded {
		byID[p.ID] = p
	}
	selected := make([]*profile.Profile, 0, len(ids))
	for _, id := range ids {
		p, ok := byID[id]
		if !ok {
			return nil, fmt.Errorf("profile %q not found under %s", id, profilesDir)
		}
		selected = append(selected, p)
	}
	return selected, nil
}

func splitCSV(raw string) []string {
	var out []string
	for _, part := range strings.Split(raw, ",") {
		part = strings.TrimSpace(part)
		if part != "" {
			out = append(out, part)
		}
	}
	return out
}

func matrixTupleDir(outDir, harness, profileID string, rep int, taskID string) string {
	return filepath.Join(outDir, "cells", safeMatrixSegment(harness), safeMatrixSegment(profileID), fmt.Sprintf("rep-%03d", rep), safeMatrixSegment(taskID))
}

func safeMatrixSegment(s string) string {
	replacer := strings.NewReplacer("/", "_", "\\", "_", ":", "_", " ", "_")
	return replacer.Replace(s)
}

func matrixAdapterModule(harness string) string {
	return "scripts.benchmark.harness_adapters." + strings.TrimSuffix(moduleFileName(harness), ".py")
}

func moduleFileName(harness string) string {
	return strings.ReplaceAll(harness, "-", "_") + ".py"
}

func matrixPrompt(task termbenchSubsetEntry) string {
	return fmt.Sprintf("Complete TerminalBench task %s.", task.ID)
}

func matrixRunKey(r matrixRunReport) string {
	return fmt.Sprintf("%s\x00%s\x00%06d\x00%s", r.Harness, r.ProfileID, r.Rep, r.TaskID)
}

func shouldSkipMatrixReport(report matrixRunReport, resume, retryBudgetHalted bool) bool {
	if !resume {
		return false
	}
	if retryBudgetHalted && report.FinalStatus == "budget_halted" {
		return false
	}

// Package profile is the canonical reader for v7 benchmark profile YAML files
// under scripts/benchmark/profiles/. The schema is frozen by SD-010 §3
// (Harness × Model Matrix Benchmark); additive fields require a spec amendment.
package profile

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

// ProviderType enumerates the four provider client paths supported by the
// matrix runner. SD-010 §3 forbids silent override; the adapter selects its
// client path by exact match on this field.
type ProviderType string

const (
	ProviderAnthropic    ProviderType = "anthropic"
	ProviderOpenAI       ProviderType = "openai"
	ProviderOpenAICompat ProviderType = "openai-compat"
	ProviderOpenRouter   ProviderType = "openrouter"
	ProviderOMLX         ProviderType = "omlx"
	ProviderLMStudio     ProviderType = "lmstudio"
	ProviderOllama       ProviderType = "ollama"
	ProviderGoogle       ProviderType = "google"
)

func (p ProviderType) valid() bool {
	switch p {
	case ProviderAnthropic, ProviderOpenAI, ProviderOpenAICompat, ProviderOpenRouter,
		ProviderOMLX, ProviderLMStudio, ProviderOllama, ProviderGoogle:
		return true
	}
	return false
}

// Provider describes how the harness adapter should reach the model API.
type Provider struct {
	Type      ProviderType `yaml:"type"`
	Model     string       `yaml:"model"`
	BaseURL   string       `yaml:"base_url"`
	APIKeyEnv string       `yaml:"api_key_env"`
}

// Pricing is the single source of truth for cost reconciliation. Units are
// USD per million tokens.
type Pricing struct {
	InputUSDPerMTok       float64 `yaml:"input_usd_per_mtok"`
	OutputUSDPerMTok      float64 `yaml:"output_usd_per_mtok"`
	CachedInputUSDPerMTok float64 `yaml:"cached_input_usd_per_mtok"`
}

// Limits captures provider-side ceilings. rate_limit_* are informational in
// v1 (D6 forbids concurrency > 1) and reserved for the follow-up scheduler.
type Limits struct {
	MaxOutputTokens int `yaml:"max_output_tokens"`
	ContextTokens   int `yaml:"context_tokens"`
	RateLimitRPM    int `yaml:"rate_limit_rpm"`
	RateLimitTPM    int `yaml:"rate_limit_tpm"`
}

// Sampling is opaque to the runner; passed verbatim to the adapter's
// apply_profile step. Reasoning is a free-form string ("low" | "medium" |
// "high" | "" depending on the family). Pointer fields are omitted when
// nil so server defaults apply.
type Sampling struct {
	Temperature float64  `yaml:"temperature"`
	Reasoning   string   `yaml:"reasoning,omitempty"`
	TopP        *float64 `yaml:"top_p,omitempty"`
	TopK        *int     `yaml:"top_k,omitempty"`
	MinP        *float64 `yaml:"min_p,omitempty"`
}

// ModelServerInfo is populated at run time by querying the local model server
// (e.g. lmstudio /api/v0/models/<id>). Fields are empty/zero when the server
// does not expose them.
type ModelServerInfo struct {
	Quantization        string `json:"quantization,omitempty"`
	LoadedContextLength int    `json:"loaded_context_length,omitempty"`
	MaxContextLength    int    `json:"max_context_length,omitempty"`
	Source              string `json:"source,omitempty"` // URL queried
}

// Versioning records when the profile was authored and which provider
// snapshot the adapter resolved at apply_profile time.
type Versioning struct {
	ResolvedAt string `yaml:"resolved_at"`
	Snapshot   string `yaml:"snapshot"`
}

// Profile is the in-memory shape of a frozen v1 profile YAML.
type Profile struct {
	ID         string     `yaml:"id"`
	Provider   Provider   `yaml:"provider"`
	Pricing    Pricing    `yaml:"pricing"`
	Limits     Limits     `yaml:"limits"`
	Sampling   Sampling   `yaml:"sampling"`
	Versioning Versioning `yaml:"versioning"`

	// Path is the filesystem path the profile was loaded from. Not part of
	// the YAML; populated by Load / LoadDir for diagnostics and `profiles
	// list` output.
	Path string `yaml:"-"`
}

// Load reads and validates a single profile YAML file at path.
func Load(path string) (*Profile, error) {
	raw, err := os.ReadFile(path) // #nosec G304 -- path is an operator-supplied profile location, scoped by Validate()
	if err != nil {
		return nil, fmt.Errorf("read profile %s: %w", path, err)
	}
	var p Profile
	dec := yaml.NewDecoder(strings.NewReader(string(raw)))
	dec.KnownFields(true)
	if err := dec.Decode(&p); err != nil {
		return nil, fmt.Errorf("parse profile %s: %w", path, err)
	}
	p.Path = path
	if err := p.Validate(); err != nil {
		return nil, fmt.Errorf("validate profile %s: %w", path, err)
	}
	return &p, nil
}

// LoadDir loads every *.yaml / *.yml file under dir, sorted by id. It is the
// entry point used by `fiz-bench profiles list`.
func LoadDir(dir string) ([]*Profile, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("read profiles dir %s: %w", dir, err)
	}
	var profiles []*Profile
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		ext := strings.ToLower(filepath.Ext(e.Name()))
		if ext != ".yaml" && ext != ".yml" {
			continue
		}
		p, err := Load(filepath.Join(dir, e.Name()))
		if err != nil {
			return nil, err
		}
		profiles = append(profiles, p)
	}
	sort.Slice(profiles, func(i, j int) bool { return profiles[i].ID < profiles[j].ID })
	return profiles, nil
}

// Validate checks that every required v1 field is present. The schema is
// frozen by SD-010 §3; missing fields are a hard error rather than a warning.
func (p *Profile) Validate() error {
	if strings.TrimSpace(p.ID) == "" {
		return fmt.Errorf("id is required")
	}
	if !p.Provider.Type.valid() {
		return fmt.Errorf("provider.type %q is not one of anthropic|openai|openrouter|omlx|lmstudio|ollama|google", p.Provider.Type)
	}
	if strings.TrimSpace(p.Provider.Model) == "" {
		return fmt.Errorf("provider.model is required")
	}
	if strings.TrimSpace(p.Provider.BaseURL) == "" {
		return fmt.Errorf("provider.base_url is required")
	}
	if strings.TrimSpace(p.Provider.APIKeyEnv) == "" {
		return fmt.Errorf("provider.api_key_env is required")
	}
	if p.Pricing.InputUSDPerMTok < 0 || p.Pricing.OutputUSDPerMTok < 0 || p.Pricing.CachedInputUSDPerMTok < 0 {
		return fmt.Errorf("pricing.* must be non-negative")
	}
	if p.Limits.MaxOutputTokens <= 0 {
		return fmt.Errorf("limits.max_output_tokens must be > 0")
	}
	if p.Limits.ContextTokens <= 0 {
		return fmt.Errorf("limits.context_tokens must be > 0")
	}
	if strings.TrimSpace(p.Versioning.ResolvedAt) == "" {
		return fmt.Errorf("versioning.resolved_at is required")
	}
	return nil
}

package profile

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
)

func writeFile(path string, data []byte) error {
	return os.WriteFile(path, data, 0o644)
}

// repoProfilesDir returns the path to scripts/benchmark/profiles/ relative
// to this test file (internal/benchmark/profile/). Three levels up.
func repoProfilesDir(t *testing.T) string {
	t.Helper()
	return filepath.Join("..", "..", "..", "scripts", "benchmark", "profiles")
}

func TestLoadDir_AllShippedProfilesValidate(t *testing.T) {
	profiles, err := LoadDir(repoProfilesDir(t))
	require.NoError(t, err)
	require.NotEmpty(t, profiles, "expected at least one shipped profile")

	ids := map[string]*Profile{}
	for _, p := range profiles {
		require.NoError(t, p.Validate(), "profile %s failed validation", p.ID)
		ids[p.ID] = p
	}

	// SD-010 §3 + bead AC: smoke + noop fixtures must ship in v1.
	require.Contains(t, ids, "smoke")
	require.Contains(t, ids, "noop")
	// Phase A.1 anchor: gpt-5-mini via OpenRouter.
	require.Contains(t, ids, "gpt-5-mini")
	// TerminalBench medium comparison lanes.
	require.Contains(t, ids, "fiz-harness-claude-sonnet-4-6")
	require.Contains(t, ids, "fiz-harness-codex-gpt-5-4-mini")
	require.Contains(t, ids, "fiz-harness-pi-gpt-5-4-mini")
	require.Contains(t, ids, "fiz-harness-opencode-gpt-5-4-mini")
	require.Contains(t, ids, "fiz-openrouter-claude-sonnet-4-6")
	require.Contains(t, ids, "fiz-openrouter-gpt-5-4-mini")
}

func TestLoad_GPT5MiniAnchorProfile(t *testing.T) {
	p, err := Load(filepath.Join(repoProfilesDir(t), "gpt-5-mini.yaml"))
	require.NoError(t, err)
	require.Equal(t, "gpt-5-mini", p.ID)
	require.Equal(t, ProviderOpenAICompat, p.Provider.Type)
	require.Equal(t, "openai/gpt-5-mini", p.Provider.Model)
	require.Equal(t, "OPENROUTER_API_KEY", p.Provider.APIKeyEnv)
	// Census §5 pricing snapshot — values must stay inside the ≤ $3/Mtok
	// output bracket that selected this row.
	require.Equal(t, 2.00, p.Pricing.OutputUSDPerMTok)
	require.Equal(t, 0.25, p.Pricing.InputUSDPerMTok)
	require.Equal(t, 0.05, p.Pricing.CachedInputUSDPerMTok)
	require.LessOrEqual(t, p.Pricing.OutputUSDPerMTok, 3.00)
	require.Equal(t, 16384, p.Limits.MaxOutputTokens)
	require.Greater(t, p.Limits.ContextTokens, 0)
	require.Greater(t, p.Limits.RateLimitRPM, 0)
	require.Greater(t, p.Limits.RateLimitTPM, 0)
	require.Equal(t, "medium", p.Sampling.Reasoning)
	require.Equal(t, "2026-04-30", p.Versioning.ResolvedAt)
	require.NotEmpty(t, p.Versioning.Snapshot)
}

func TestLoad_SmokeProfileFields(t *testing.T) {
	p, err := Load(filepath.Join(repoProfilesDir(t), "smoke.yaml"))
	require.NoError(t, err)
	require.Equal(t, "smoke", p.ID)
	require.Equal(t, ProviderOpenAICompat, p.Provider.Type)
	require.Equal(t, "OPENAI_API_KEY", p.Provider.APIKeyEnv)
	require.Greater(t, p.Limits.MaxOutputTokens, 0)
	require.Greater(t, p.Limits.ContextTokens, 0)
	require.NotEmpty(t, p.Versioning.ResolvedAt)
	require.NotEmpty(t, p.Path)
}

func TestLoad_NoopProfileFields(t *testing.T) {
	p, err := Load(filepath.Join(repoProfilesDir(t), "noop.yaml"))
	require.NoError(t, err)
	require.Equal(t, "noop", p.ID)
	require.Equal(t, ProviderOpenAICompat, p.Provider.Type)
	require.Equal(t, 0.0, p.Pricing.InputUSDPerMTok)
	require.Equal(t, "noop-fixture", p.Versioning.Snapshot)
}

func TestValidate_RejectsMissingFields(t *testing.T) {
	cases := []struct {
		name    string
		mutate  func(p *Profile)
		wantSub string
	}{
		{"missing id", func(p *Profile) { p.ID = "" }, "id is required"},
		{"bad provider type", func(p *Profile) { p.Provider.Type = "bedrock" }, "provider.type"},
		{"missing model", func(p *Profile) { p.Provider.Model = "" }, "provider.model"},
		{"missing base_url", func(p *Profile) { p.Provider.BaseURL = "" }, "provider.base_url"},
		{"missing api_key_env", func(p *Profile) { p.Provider.APIKeyEnv = "" }, "provider.api_key_env"},
		{"negative pricing", func(p *Profile) { p.Pricing.InputUSDPerMTok = -1 }, "pricing"},
		{"zero max_output", func(p *Profile) { p.Limits.MaxOutputTokens = 0 }, "max_output_tokens"},
		{"zero context", func(p *Profile) { p.Limits.ContextTokens = 0 }, "context_tokens"},
		{"missing resolved_at", func(p *Profile) { p.Versioning.ResolvedAt = "" }, "resolved_at"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			p := goodProfile()
			tc.mutate(&p)
			err := p.Validate()
			require.Error(t, err)
			require.Contains(t, err.Error(), tc.wantSub)
		})
	}
}

func TestLoad_RejectsUnknownFields(t *testing.T) {
	dir := t.TempDir()
	bad := filepath.Join(dir, "bad.yaml")
	require.NoError(t, writeFile(bad, []byte(`
id: bad
provider: {type: openai, model: m, base_url: https://x, api_key_env: K}
pricing: {input_usd_per_mtok: 1, output_usd_per_mtok: 1, cached_input_usd_per_mtok: 0}
limits: {max_output_tokens: 1, context_tokens: 1, rate_limit_rpm: 1, rate_limit_tpm: 1}
sampling: {temperature: 0}
versioning: {resolved_at: "2026-04-29", snapshot: ""}
unknown_top_level: oops
`)))
	_, err := Load(bad)
	require.Error(t, err)
}

func goodProfile() Profile {
	return Profile{
		ID: "x",
		Provider: Provider{
			Type:      ProviderOpenAI,
			Model:     "m",
			BaseURL:   "https://api.example.com",
			APIKeyEnv: "K",
		},
		Pricing:    Pricing{InputUSDPerMTok: 1, OutputUSDPerMTok: 1},
		Limits:     Limits{MaxOutputTokens: 1024, ContextTokens: 8192},
		Sampling:   Sampling{Temperature: 0},
		Versioning: Versioning{ResolvedAt: "2026-04-29"},
	}
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/DocumentDrivenDX/fizeau/internal/benchmark/profile"
)

const defaultProfilesDir = "scripts/benchmark/profiles"

func cmdProfiles(args []string) int {
	if len(args) == 0 {
		fmt.Fprintf(os.Stderr, "Usage: %s profiles <subcommand>\n\nSubcommands:\n  list   List profiles under scripts/benchmark/profiles/\n", benchCommandName())
		return 2
	}
	switch args[0] {
	case "list":
		return cmdProfilesList(args[1:])
	case "help", "-h", "--help":
		fmt.Fprintf(os.Stderr, "Usage: %s profiles list [--dir <path>] [--json]\n", benchCommandName())
		return 0
	default:
		fmt.Fprintf(os.Stderr, "%s profiles: unknown subcommand %q\n", benchCommandName(), args[0])
		return 2
	}
}

func cmdProfilesList(args []string) int {
	fs := flagSet("profiles list")
	dir := fs.String("dir", "", "Profiles directory (default: scripts/benchmark/profiles relative to --work-dir)")
	workDir := fs.String("work-dir", "", "Repository root (default: cwd)")
	jsonOut := fs.Bool("json", false, "Emit JSON array instead of table")
	if err := fs.Parse(args); err != nil {
		return 2
	}

	profilesDir := *dir
	if profilesDir == "" {
		profilesDir = filepath.Join(resolveWorkDir(*workDir), defaultProfilesDir)
	}

	profiles, err := profile.LoadDir(profilesDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s profiles list: %v\n", benchCommandName(), err)
		return 1
	}

	if *jsonOut {
		data, _ := json.MarshalIndent(profiles, "", "  ")
		fmt.Println(string(data))
		return 0
	}

	if len(profiles) == 0 {
		fmt.Printf("No profiles found in %s.\n", profilesDir)
		return 0
	}

	fmt.Printf("%-24s %-14s %-32s %-12s %-12s\n", "ID", "PROVIDER", "MODEL", "IN $/Mtok", "OUT $/Mtok")
	fmt.Printf("%-24s %-14s %-32s %-12s %-12s\n", "--", "--------", "-----", "---------", "----------")
	for _, p := range profiles {
		fmt.Printf("%-24s %-14s %-32s %-12.4f %-12.4f\n",
			p.ID,
			string(p.Provider.Type),
			p.Provider.Model,
			p.Pricing.InputUSDPerMTok,
			p.Pricing.OutputUSDPerMTok,
		)
	}
	return 0
}
